# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# SCI8-form instructions (VLEPEM Rev. 0 Figure A-15).  The immediate is
# synthesized from F, SCL and UI8; the lowest SCL is used, as in GNU as.

# CHECK: e_addi 3, 4, 0 # encoding: [0x18,0x64,0x80,0x00]
e_addi 3, 4, 0
# CHECK: e_addi 3, 4, 1 # encoding: [0x18,0x64,0x80,0x01]
e_addi 3, 4, 1
# CHECK: e_addi 3, 4, -1 # encoding: [0x18,0x64,0x84,0xff]
e_addi 3, 4, -1
# CHECK: e_addi 3, 4, 256 # encoding: [0x18,0x64,0x81,0x01]
e_addi 3, 4, 0x100
# CHECK: e_addi 3, 4, 65280 # encoding: [0x18,0x64,0x81,0xff]
e_addi 3, 4, 0xff00
# CHECK: e_addi 3, 4, 65536 # encoding: [0x18,0x64,0x82,0x01]
e_addi 3, 4, 0x10000
# CHECK: e_addi 3, 4, -256 # encoding: [0x18,0x64,0x84,0x00]
e_addi 3, 4, 0xffffff00
# CHECK: e_addi 3, 4, -16777216 # encoding: [0x18,0x64,0x83,0xff]
e_addi 3, 4, 0xff000000
# CHECK: e_addi 3, 4, 16711680 # encoding: [0x18,0x64,0x82,0xff]
e_addi 3, 4, 0x00ff0000
# CHECK: e_addi 3, 4, -65281 # encoding: [0x18,0x64,0x85,0x00]
e_addi 3, 4, 0xffff00ff
# CHECK: e_addi. 3, 4, 1 # encoding: [0x18,0x64,0x88,0x01]
e_addi. 3, 4, 1
# CHECK: e_addic 3, 4, 1 # encoding: [0x18,0x64,0x90,0x01]
e_addic 3, 4, 1
# CHECK: e_addic. 3, 4, 1 # encoding: [0x18,0x64,0x98,0x01]
e_addic. 3, 4, 1
# CHECK: e_mulli 3, 4, -1 # encoding: [0x18,0x64,0xa4,0xff]
e_mulli 3, 4, -1
# CHECK: e_subfic 3, 4, -1 # encoding: [0x18,0x64,0xb4,0xff]
e_subfic 3, 4, -1
# CHECK: e_subfic. 3, 4, 1 # encoding: [0x18,0x64,0xb8,0x01]
e_subfic. 3, 4, 1
# CHECK: e_andi 3, 4, 1 # encoding: [0x18,0x83,0xc0,0x01]
e_andi 3, 4, 1
# CHECK: e_andi. 3, 4, 1 # encoding: [0x18,0x83,0xc8,0x01]
e_andi. 3, 4, 1
# CHECK: e_ori 3, 4, 1 # encoding: [0x18,0x83,0xd0,0x01]
e_ori 3, 4, 1
# CHECK: e_ori. 3, 4, 1 # encoding: [0x18,0x83,0xd8,0x01]
e_ori. 3, 4, 1
# CHECK: e_xori 3, 4, 1 # encoding: [0x18,0x83,0xe0,0x01]
e_xori 3, 4, 1
# CHECK: e_xori. 3, 4, 1 # encoding: [0x18,0x83,0xe8,0x01]
e_xori. 3, 4, 1
# CHECK: e_cmpi 0, 3, 1 # encoding: [0x18,0x03,0xa8,0x01]
e_cmpi 0, 3, 1
# CHECK: e_cmpi 3, 3, -1 # encoding: [0x18,0x63,0xac,0xff]
e_cmpi 3, 3, -1
# CHECK: e_cmpli 1, 3, 1 # encoding: [0x18,0xa3,0xa8,0x01]
e_cmpli 1, 3, 1
# CHECK: e_cmpli 1, 3, -1 # encoding: [0x18,0xa3,0xac,0xff]
e_cmpli 1, 3, -1
